-- Bulk-populate audiobook_editions with edition_type='standard' rows,
-- sourced from Hardcover's per-edition contributor data (confirmed
-- 2026-09-11 that narrator data is exposed as a contribution: "Narrator"
-- role, genuinely bulk-fetchable -- see docs/TODO.md). Generated by
-- scripts/backfill-standard-narrators.js against all 869 catalog books
-- with a hardcover_id.
--
-- Why only 605 of 869: the script groups each book's audio editions by
-- narrator-set identity (not by publisher/date, which vary across
-- reprints of the same performance) specifically to avoid conflating
-- genuinely different narrations of the same book -- confirmed on The
-- Eye of the World, which has both the classic Kramer/Reading narration
-- and a separate 2021 Rosamund Pike re-recording; a naive one-row-per-
-- book approach would have silently picked one or blended both casts.
-- 578 books produced exactly one confident narrator group (578 rows);
-- 27 of those produced two genuine, well-attested groups (54 rows,
-- included here), accounting for the 605 total. The remaining 264
-- books were deliberately NOT inserted here, left for a follow-up pass:
-- 130 had an ambiguous second group with weak/no community signal
-- (likely a data-entry variant, e.g. "Michael Krammer" vs "Michael
-- Kramer" on Mistborn: The Final Empire, not a real second narration),
-- 78 had 3+ distinct groups (mostly public-domain classics with many
-- real historical narrations -- Frankenstein alone has 12), 65 had no
-- narrator-labeled contributor in Hardcover's data at all, and 18 had
-- no audio edition listed. None of these were guessed at -- see
-- docs/TODO.md for the follow-up item.
--
-- Every insert is title/author-scoped (never a raw UUID, per this
-- project's standing convention) and idempotent via the existing
-- unique (book_id, source_url) constraint. Verified: every one of the
-- 578 books' title/author pairs matches exactly one books row before
-- this file was generated (zero mismatches on a direct DB check).

insert into audiobook_editions (book_id, edition_type, narrators, production_company, runtime_minutes, source_url, last_verified_date)
select id, 'standard', ARRAY['Craig Wasson']::text[], 'Hachette UK', 1839, 'https://hardcover.app/books/11-22-63/editions/30422955', current_date
from books where title = '11/22/63' and author = 'Stephen King'
on conflict (book_id, source_url) do nothing;

